    let heat = sess.flag;
    let frost = prep(&sess, &pool);
    load::step(&mut sess, &mut pool, &plan);

    let frost_items = values(&frost.ids.borrow(), &frost.cells);
    let live_items = values(&sess.ids.borrow(), &pool.cells);
    if heat && frost_items == live_items {
        return 3;
    }

    let body = format!(
        "{{\"tick\":{},\"mark\":{},\"frost_bag\":{},\"live_bag\":{}}}\n",
        sess.n0.saturating_add(tally::lines()),
        sess.n1,
