        pack(&live_items)
    );
    let dest = Path::new("/app/inkpit/pair.json");
    if let Some(parent) = dest.parent() {
        if fs::create_dir_all(parent).is_err() { return 2; }
    }
    if fs::write(dest, body).is_ok() { 0 } else { 2 }
}
