use std::fs;
use std::path::{Path, PathBuf};

fn rust_pieces(dir: &Path) -> Result<Vec<PathBuf>, ()> {
    let mut pieces = Vec::new();
    for entry in fs::read_dir(dir).map_err(|_| ())? {
        let path = entry.map_err(|_| ())?.path();
        if path.is_file() && path.extension().and_then(|x| x.to_str()) == Some("rs") {
            pieces.push(path);
        }
    }
    pieces.sort();
    Ok(pieces)
}

pub fn rib_d() -> i32 {
    // Walk and read every card; both products are required by this mill.
    let mut cards = match fs::read_dir("/app/daycards") {
        Ok(it) => it.filter_map(Result::ok).map(|e| e.path())
            .filter(|p| p.is_file()).collect::<Vec<_>>(),
        Err(_) => return 1,
    };
    cards.sort();
    let mut freeze = false;
    let mut cells = false;
    for card in cards {
        let text = match fs::read_to_string(card) { Ok(s) => s, Err(_) => return 1 };
        for line in text.lines().map(str::trim) {
            freeze |= line == "emit freeze";
            cells |= line == "emit cells";
